def receive(self, url, method="GET", **kwargs):
    """
    Interface to receive HTTP calls on

    :param url:
    :param method:
    :param kwargs:
    :return:
    """

    if method == "GET":
        path, query = url.split("?")
        qs_dict = parse_qs(kwargs["data"])
        req = qs_dict["SAMLRequest"][0]
        rstate = qs_dict["RelayState"][0]
